import { useEffect, useState } from 'react'
import { CreditCard } from 'lucide-react'
import { debtApi, type Debt, type Vendor } from '../../api'
import { Button } from '../../components/ui/button'
import { Card, CardContent } from '../../components/ui/card'
import { Input } from '../../components/ui/input'

export function DebtPage({ vendor }: { vendor?: Vendor }) { const [accounts, setAccounts] = useState<Debt[]>([]); const [selected, setSelected] = useState<Debt | null>(null); const [amount, setAmount] = useState(''); const [notes, setNotes] = useState(''); const [message, setMessage] = useState(''); const load = () => { if (vendor) debtApi.accounts(vendor.id).then(setAccounts).catch(() => setAccounts([])) }; useEffect(load, [vendor]); async function pay() { if (!vendor || !selected || !amount) return; try { await debtApi.pay(vendor.id, selected.id, Number(amount), notes); setMessage('Payment recorded.'); setAmount(''); setNotes(''); load() } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to record payment.') } } return <><PageIntro title="Debt & credit" text="Track customer balances, payment history, and outstanding credit accounts." />{message && <p className="mb-4 rounded-xl bg-emerald-50 p-3 text-sm font-semibold text-emerald-700">{message}</p>}<div className="grid gap-5 xl:grid-cols-[1fr_330px]"><Card><CardContent className="p-4"><div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b border-slate-100 text-xs uppercase text-slate-500"><tr><th className="px-3 py-3">Customer</th><th className="px-3 py-3">Credit</th><th className="px-3 py-3">Paid</th><th className="px-3 py-3">Balance</th><th className="px-3 py-3">Status</th></tr></thead><tbody>{accounts.map(account => <tr key={account.id} onClick={() => setSelected(account)} className={`cursor-pointer border-b border-slate-50 ${selected?.id === account.id ? 'bg-indigo-50' : ''}`}><td className="px-3 py-3 font-semibold">{account.customerName}</td><td className="px-3 py-3">PHP {account.totalCredit.toLocaleString()}</td><td className="px-3 py-3">PHP {account.totalPaid.toLocaleString()}</td><td className="px-3 py-3 font-bold">PHP {account.balance.toLocaleString()}</td><td className="px-3 py-3 text-xs font-bold">{account.status}</td></tr>)}</tbody></table>{!accounts.length && <p className="p-8 text-center text-sm text-slate-500">No debt accounts found.</p>}</div></CardContent></Card><Card><CardContent className="p-5"><CreditCard className="text-indigo-600" size={20} /><h2 className="mt-3 font-bold">Record payment</h2><p className="mt-1 text-xs text-slate-500">{selected ? `${selected.customerName} · Balance PHP ${selected.balance.toLocaleString()}` : 'Select an account first.'}</p><div className="mt-4 space-y-3"><Input type="number" min="0" placeholder="Payment amount" value={amount} onChange={event => setAmount(event.target.value)} /><Input placeholder="Notes" value={notes} onChange={event => setNotes(event.target.value)} /><Button className="w-full" disabled={!selected || !amount} onClick={pay}>Record payment</Button></div></CardContent></Card></div></> }
function PageIntro({ title, text }: { title: string; text: string }) { return <div className="mb-6"><p className="text-[11px] font-bold uppercase tracking-[.17em] text-indigo-600">Customer accounts</p><h1 className="mt-1.5 text-3xl font-black tracking-[-.055em]">{title}</h1><p className="mt-2 text-[13px] text-slate-500">{text}</p></div> }
